    def __init__(self, owner):
        self.owner = owner
        self.daily_steps = []

    def record(self, steps):
        if steps >= 0:
            self.daily_steps.append(steps)

    def best_day(self):
        if not self.daily_steps:
            return 0
        return max(self.daily_steps)

    def goal_days(self, goal):
